import pysam, json, subprocess, os
from scipy.stats import fisher_exact

CHROM='chr22_panel'
genome=pysam.FastaFile('/task/input/reference/ref.fa')
GLEN=genome.lengths[genome.references.index(CHROM)]

targets=[]
for line in open('/task/input/targets.bed'):
    f=line.split()
    targets.append((f[0],int(f[1]),int(f[2])))

pairs={'PT-0452':('CG24-4187','CG24-1366'),'PT-0740':('CG24-7410','CG24-6425'),'PT-0760':('CG24-9024','CG24-3973')}
alls=set()
for t,n in pairs.values(): alls.add(t); alls.add(n)
bams={s:pysam.AlignmentFile('/task/work/bam/%s.bam'%s) for s in alls}

def get_ref(pos0,l=1):
    return genome.fetch(CHROM,pos0,pos0+l).upper()

def snv_cands(bam):
    out={}
    for ch,s,e in targets:
        for col in bam.pileup(ch,s,e,min_base_quality=20,min_mapping_quality=20,max_depth=1000000):
            pos=col.reference_pos
            refb=get_ref(pos)
            counts={}
            for pr in col.pileups:
                if pr.is_del or pr.is_refskip: continue
                b=pr.alignment.query_sequence[pr.query_position].upper()
                counts[b]=counts.get(b,0)+1
            tot=sum(counts.values())
            if tot==0: continue
            for b,c in counts.items():
                if b!=refb and c>=3 and c/tot>=0.02:
                    out[pos]=(refb,b)
    return out

def indel_cands(bam):
    ev={}
    for ch,s,e in targets:
        for r in bam.fetch(ch,s,e):
            if r.is_unmapped or r.is_secondary or r.is_supplementary or r.mapping_quality<20: continue
            rp=r.reference_start; qp=0
            for op,l in (r.cigartuples or []):
                if op in (0,7,8): rp+=l; qp+=l
                elif op==1:
                    if 1<=l<=30:
                        seq=r.query_sequence[qp:qp+l]
                        k=('I',rp-1,l,seq)
                        ev[k]=ev.get(k,0)+1
                    qp+=l
                elif op==2:
                    if 1<=l<=30:
                        k=('D',rp,l,None)
                        ev[k]=ev.get(k,0)+1
                    rp+=l
                elif op==4: qp+=l
    return {k:c for k,c in ev.items() if c>=3}

def frag_count(bam,kind,target):
    frag={}; strands={}
    if kind=='snv':
        pos0,refb,altb=target
        lo,hi=pos0,pos0+1
    else:
        typ,x,l,seq=target
        anchor=x if typ=='I' else x-1
        lo,hi=max(0,anchor-2),anchor+3+l
    for r in bam.fetch(CHROM,lo,hi):
        if r.is_unmapped or r.is_secondary or r.is_supplementary or r.mapping_quality<20: continue
        if kind=='snv':
            q=None
            for qp,rp in r.get_aligned_pairs(matches_only=False):
                if rp==pos0: q=qp; break
            if q is None: continue
            if r.query_qualities is None or r.query_qualities[q]<20: continue
            b=r.query_sequence[q].upper()
            a='ALT' if b==altb else ('REF' if b==refb else 'OTHER')
        else:
            typ,x,l,seq=target
            rp=r.reference_start; qp=0; found=False; conf=False
            for op,ln in (r.cigartuples or []):
                if op in (0,7,8): rp+=ln; qp+=ln
                elif op==1:
                    if typ=='I' and rp-1==x and ln==l and r.query_sequence[qp:qp+ln]==seq: found=True
                    elif abs((rp-1)-x)<=2: conf=True
                    qp+=ln
                elif op==2:
                    if typ=='D' and rp==x and ln==l: found=True
                    elif abs(rp-x)<=2: conf=True
                    rp+=ln
                elif op==4: qp+=ln
            if typ=='I':
                spans=r.reference_start<=x and r.reference_end>=x+2
            else:
                spans=r.reference_start<=x-1 and r.reference_end>=x+l+1
            if found: a='ALT'
            elif conf: a='OTHER'
            elif spans: a='REF'
            else: continue
        frag.setdefault(r.query_name,set()).add(a)
        strands.setdefault(r.query_name,set()).add((a,r.is_reverse))
    refc=altc=0; astr=set()
    for k,v in frag.items():
        if len(v)==1:
            a=next(iter(v))
            if a=='ALT':
                altc+=1
                for (aa,rev) in strands[k]:
                    if aa=='ALT': astr.add(rev)
            elif a=='REF': refc+=1
    return refc,altc,astr

os.makedirs('/task/output/somatic',exist_ok=True)
summary={'patients':{}}
pairrows=[]
for pat,(t,n) in pairs.items():
    bt=bams[t]; bn=bams[n]
    sc=snv_cands(bt); ic=indel_cands(bt)
    recs=[]
    def decide(label,pos1,ref,alt,rt,at,st,rn,an):
        dt=rt+at; dn=rn+an
        aft=at/dt if dt else 0.0; afn=an/dn if dn else 0.0
        p=fisher_exact([[at,rt],[an,rn]],alternative='greater')[1] if (dt and dn) else 1.0
        ok=True; why=[]
        if dt<20: ok=False; why.append('lowTdepth')
        if at<4: ok=False; why.append('lowAlt')
        if aft<0.05: ok=False; why.append('lowVAF')
        if dn<10: ok=False; why.append('lowNdepth')
        if afn>=0.05: ok=False; why.append('germline')
        if p>0.01: ok=False; why.append('p=%.2g'%p)
        if at>=10 and len(st)<2: ok=False; why.append('strand')
        print(pat,label,pos1,ref,alt,'T:%d/%d AF=%.3f'%(at,dt,aft),'N:%d/%d AF=%.3f'%(an,dn,afn),'p=%.2e'%p,'PASS' if ok else 'FAIL:'+';'.join(why))
        return ok,aft
    for pos0,(refb,altb) in sorted(sc.items()):
        rt,at,st=frag_count(bt,'snv',(pos0,refb,altb))
        rn,an,_=frag_count(bn,'snv',(pos0,refb,altb))
        ok,aft=decide('SNV',pos0+1,refb,altb,rt,at,st,rn,an)
        if ok: recs.append((pos0+1,refb,altb,aft))
    for k in sorted(ic.keys(),key=lambda z:z[1]):
        typ,x,l,seq=k
        if typ=='I':
            pos1=x+1; ref=get_ref(x); alt=ref+seq
        else:
            pos1=x; ref=get_ref(x-1,1+l); alt=get_ref(x-1)
        rt,at,st=frag_count(bt,'indel',k)
        rn,an,_=frag_count(bn,'indel',k)
        ok,aft=decide('INDEL',pos1,ref,alt,rt,at,st,rn,an)
        if ok: recs.append((pos1,ref,alt,aft))
    recs.sort()
    pre='/task/work/%s.pre.vcf'%pat
    with open(pre,'w') as fh:
        fh.write('##fileformat=VCFv4.2\n')
        fh.write('##contig=<ID=%s,length=%d>\n'%(CHROM,GLEN))
        fh.write('##FILTER=<ID=PASS,Description="All filters passed">\n')
        fh.write('##INFO=<ID=AF,Number=A,Type=Float,Description="Fraction of tumour DNA fragments carrying the alternate allele">\n')
        fh.write('#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\n')
        for pos1,ref,alt,af in recs:
            fh.write('%s\t%d\t.\t%s\t%s\t.\tPASS\tAF=%s\n'%(CHROM,pos1,ref,alt,round(af,4)))
    out='/task/output/somatic/%s.vcf.gz'%pat
    subprocess.run(['bcftools','norm','-f','/task/input/reference/ref.fa','-Oz','-o',out,pre],check=True)
    subprocess.run(['tabix','-f','-p','vcf',out],check=True)
    n_snv=n_indel=0
    vf=pysam.VariantFile(out)
    for rec in vf:
        if 'PASS' not in rec.filter.keys(): continue
        alt=rec.alts[0]
        if len(rec.ref)==1 and len(alt)==1: n_snv+=1
        else: n_indel+=1
    summary['patients'][pat]={'tumour_sample':t,'normal_sample':n,'n_snv':n_snv,'n_indel':n_indel}
    pairrows.append((pat,t,n))
    print(pat,'n_snv=%d n_indel=%d'%(n_snv,n_indel))

with open('/task/output/pairing.tsv','w') as fh:
    fh.write('patient\ttumour_sample\tnormal_sample\n')
    for pat,t,n in pairrows:
        fh.write('%s\t%s\t%s\n'%(pat,t,n))
with open('/task/output/summary.json','w') as fh:
    json.dump(summary,fh,indent=2)
print('ALL DONE')
